parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "id": {
      "type": "integer",
      "description": "The identifier of the epic, copied from the line 'ID : <id>' under the epic heading."
    },
    "description": {
      "type": "string",
      "description": "The whole epic, verbatim, from '## Description' to the end of the last measure, with the three section headings. Without the title, the ID line, the marker and the Features section."
    },
    "features": {
      "type": "array",
      "description": "The features of the epic, one per line of the Features section, in the original order.",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": ["integer", "null"],
            "description": "The identifier copied after 'ID :' at the end of the feature line. null when the line has no ID (new feature)."
          },
          "title": {
            "type": "string",
            "description": "The feature title, without the number (F1...) and without bold marks."
          },
          "description": {
            "type": "string",
            "description": "The sentence of value after the long dash, unchanged, without the priority mention and without the ID mention."
          },
          "priority": {
            "type": "string",
            "enum": ["Highest", "High", "Medium", "Low", "Lowest"],
            "description": "The priority copied after 'Priorité :'."
          }
        },
        "required": ["title", "description", "priority"]
      }
    }
  },
  "required": ["id", "description", "features"]
}

